using System;
using Framework.AI.Core;
using Framework.Parameters;
using UnityEngine;

namespace Game.Tests
{
    /// <summary>
    /// エージェントの共有情報、稼働状態、
    /// 更新処理およびライフサイクルを検証する。
    /// </summary>
    [DisallowMultipleComponent]
    public sealed class AgentCoreTest : MonoBehaviour
    {
        [Header("テスト設定")]
        [SerializeField]
        [Tooltip("開始時にすべてのテストを実行する。")]
        private bool runTestsOnStart = true;

        [Header("テスト結果")]
        [SerializeField]
        [Tooltip("成功したテスト件数。")]
        private int passedCount;

        [SerializeField]
        [Tooltip("失敗したテスト件数。")]
        private int failedCount;

        /// <summary>
        /// テスト用パラメーター識別子。
        /// </summary>
        private enum TestParameterId
        {
            /// <summary>
            /// 移動速度。
            /// </summary>
            MoveSpeed,

            /// <summary>
            /// 攻撃性。
            /// </summary>
            Aggression
        }

        /// <summary>
        /// 基本機能の検証に使用する仮想エージェント。
        /// </summary>
        private sealed class TestAgent :
            AgentBase<TestParameterId>
        {
            /// <summary>
            /// 初期化処理の実行件数。
            /// </summary>
            public int InitializeCount { get; private set; }

            /// <summary>
            /// 稼働開始処理の実行件数。
            /// </summary>
            public int ActivateCount { get; private set; }

            /// <summary>
            /// 稼働停止処理の実行件数。
            /// </summary>
            public int DeactivateCount { get; private set; }

            /// <summary>
            /// 一時停止処理の実行件数。
            /// </summary>
            public int PauseCount { get; private set; }

            /// <summary>
            /// 稼働再開処理の実行件数。
            /// </summary>
            public int ResumeCount { get; private set; }

            /// <summary>
            /// 破棄処理の実行件数。
            /// </summary>
            public int DisposeCount { get; private set; }

            /// <summary>
            /// 最後に受け取った経過時間。
            /// </summary>
            public float LastDeltaTime { get; private set; }

            /// <summary>
            /// 更新時に実行する追加テスト処理。
            /// </summary>
            public Action TickAction { get; set; }

            /// <summary>
            /// 初期化処理の実行を記録する。
            /// </summary>
            protected override void OnInitialize()
            {
                InitializeCount++;
            }

            /// <summary>
            /// 稼働開始処理の実行を記録する。
            /// </summary>
            protected override void OnActivated()
            {
                ActivateCount++;
            }

            /// <summary>
            /// 稼働停止処理の実行を記録する。
            /// </summary>
            protected override void OnDeactivated()
            {
                DeactivateCount++;
            }

            /// <summary>
            /// 一時停止処理の実行を記録する。
            /// </summary>
            protected override void OnPaused()
            {
                PauseCount++;
            }

            /// <summary>
            /// 稼働再開処理の実行を記録する。
            /// </summary>
            protected override void OnResumed()
            {
                ResumeCount++;
            }

            /// <summary>
            /// 更新時の経過時間と追加処理を記録する。
            /// </summary>
            /// <param name="deltaTime">経過時間。単位は秒</param>
            protected override void OnTick(float deltaTime)
            {
                LastDeltaTime = deltaTime;

                TickAction?.Invoke();
            }

            /// <summary>
            /// 破棄処理の実行を記録する。
            /// </summary>
            protected override void OnDispose()
            {
                DisposeCount++;
            }
        }

        /// <summary>
        /// 開始時のテスト実行を制御する。
        /// </summary>
        private void Start()
        {
            if (runTestsOnStart)
            {
                RunAllTests();
            }
        }

        /// <summary>
        /// すべてのテストを実行する。
        /// </summary>
        [ContextMenu("すべてのテストを実行")]
        public void RunAllTests()
        {
            passedCount = 0;
            failedCount = 0;

            try
            {
                TestContext();
                TestInitialization();
                TestStateTransitions();
                TestTick();
                TestEvents();
                TestIndependence();
                TestDisposal();
                TestInvalidInput();
            }
            catch (Exception exception)
            {
                failedCount++;

                Debug.LogException(exception, this);
            }

            Debug.Log(
                $"【AgentCore テスト結果】\n" +
                $"成功：{passedCount}\n" +
                $"失敗：{failedCount}\n" +
                (failedCount == 0
                    ? "すべてのテストに成功しました。"
                    : "失敗したテストを確認してください。"),
                this);
        }

        /// <summary>
        /// テスト用パラメーター集合を生成する。
        /// </summary>
        /// <returns>標準パラメーター集合</returns>
        private ParameterSet<TestParameterId>
            CreateParameters()
        {
            return new ParameterSet<TestParameterId>(
                new[]
                {
                    new ParameterDefinition<TestParameterId>(
                        TestParameterId.MoveSpeed,
                        4f,
                        0f,
                        10f),

                    new ParameterDefinition<TestParameterId>(
                        TestParameterId.Aggression,
                        0.5f,
                        0f,
                        1f)
                });
        }

        /// <summary>
        /// テスト用共有情報を生成する。
        /// </summary>
        /// <param name="parameters">パラメーター集合</param>
        /// <returns>テスト用共有情報</returns>
        private AgentContext<TestParameterId> CreateContext(
            ParameterSet<TestParameterId> parameters)
        {
            return new AgentContext<TestParameterId>(
                "TestAgent",
                parameters);
        }

        /// <summary>
        /// 共有情報の生成と参照を検証する。
        /// </summary>
        private void TestContext()
        {
            using (var parameters = CreateParameters())
            {
                var context = CreateContext(parameters);

                bool idPassed =
                    context.Id != Guid.Empty;
                Debug.Assert(idPassed, "識別子の自動生成", this);
                Check(idPassed, "識別子の自動生成");

                bool namePassed =
                    context.Name == "TestAgent";
                Debug.Assert(namePassed, "表示名の保持", this);
                Check(namePassed, "表示名の保持");

                bool referencePassed =
                    ReferenceEquals(
                        context.Parameters,
                        parameters);
                Debug.Assert(referencePassed, "パラメーター参照の保持", this);
                Check(referencePassed, "パラメーター参照の保持");

                Guid customId = Guid.NewGuid();

                var customContext =
                    new AgentContext<TestParameterId>(
                        customId,
                        "CustomAgent",
                        parameters);

                bool customPassed =
                    customContext.Id == customId;
                Debug.Assert(customPassed, "指定識別子での生成", this);
                Check(customPassed, "指定識別子での生成");
            }
        }

        /// <summary>
        /// エージェントの初期化処理を検証する。
        /// </summary>
        private void TestInitialization()
        {
            using (var parameters = CreateParameters())
            using (var agent = new TestAgent())
            {
                bool initialPassed =
                    agent.State == AgentState.Uninitialized &&
                    !agent.IsInitialized &&
                    !agent.IsTickEnabled;
                Debug.Assert(initialPassed, "未初期化状態", this);
                Check(initialPassed, "未初期化状態");

                var context = CreateContext(parameters);

                bool initializePassed =
                    agent.Initialize(context) &&
                    agent.IsInitialized &&
                    agent.State == AgentState.Inactive;
                Debug.Assert(initializePassed, "エージェントの初期化", this);
                Check(initializePassed, "エージェントの初期化");

                bool contextPassed =
                    ReferenceEquals(agent.Context, context) &&
                    agent.Id == context.Id &&
                    agent.Name == context.Name &&
                    agent.InitializeCount == 1;
                Debug.Assert(contextPassed, "共有情報と初期化処理", this);
                Check(contextPassed, "共有情報と初期化処理");

                bool duplicatePassed =
                    !agent.Initialize(context) &&
                    agent.InitializeCount == 1;
                Debug.Assert(duplicatePassed, "重複初期化の拒否", this);
                Check(duplicatePassed, "重複初期化の拒否");
            }
        }

        /// <summary>
        /// 稼働状態の遷移を検証する。
        /// </summary>
        private void TestStateTransitions()
        {
            using (var parameters = CreateParameters())
            using (var agent = new TestAgent())
            {
                bool invalidPassed =
                    !agent.Activate() &&
                    !agent.Pause() &&
                    !agent.Resume() &&
                    !agent.Deactivate();
                Debug.Assert(invalidPassed, "未初期化時の状態変更拒否", this);
                Check(invalidPassed, "未初期化時の状態変更拒否");

                agent.Initialize(CreateContext(parameters));

                bool activePassed =
                    agent.Activate() &&
                    agent.IsActive &&
                    agent.IsTickEnabled &&
                    agent.ActivateCount == 1;
                Debug.Assert(activePassed, "稼働開始", this);
                Check(activePassed, "稼働開始");

                bool duplicatePassed =
                    !agent.Activate() &&
                    agent.ActivateCount == 1;
                Debug.Assert(duplicatePassed, "重複稼働開始の拒否", this);
                Check(duplicatePassed, "重複稼働開始の拒否");

                bool pausePassed =
                    agent.Pause() &&
                    agent.IsPaused &&
                    !agent.IsTickEnabled &&
                    agent.PauseCount == 1;
                Debug.Assert(pausePassed, "一時停止", this);
                Check(pausePassed, "一時停止");

                bool resumePassed =
                    agent.Resume() &&
                    agent.IsActive &&
                    agent.ResumeCount == 1;
                Debug.Assert(resumePassed, "稼働再開", this);
                Check(resumePassed, "稼働再開");

                agent.Pause();

                bool inactivePassed =
                    agent.Deactivate() &&
                    agent.State == AgentState.Inactive &&
                    agent.DeactivateCount == 1;
                Debug.Assert(inactivePassed, "一時停止状態からの非稼働化", this);
                Check(inactivePassed, "一時停止状態からの非稼働化");
            }
        }

        /// <summary>
        /// 更新処理と更新統計を検証する。
        /// </summary>
        private void TestTick()
        {
            using (var parameters = CreateParameters())
            using (var agent = new TestAgent())
            {
                agent.Initialize(CreateContext(parameters));

                agent.Tick(0.25f);

                bool inactivePassed =
                    agent.TickCount == 0;
                Debug.Assert(inactivePassed, "非稼働時の更新抑止", this);
                Check(inactivePassed, "非稼働時の更新抑止");

                agent.Activate();

                agent.Tick(0.25f);

                bool activePassed =
                    agent.TickCount == 1 &&
                    agent.LastDeltaTime == 0.25f;
                Debug.Assert(activePassed, "稼働中の更新処理", this);
                Check(activePassed, "稼働中の更新処理");

                agent.Tick(0.5f);

                bool timePassed =
                    agent.TickCount == 2 &&
                    agent.ElapsedTickTime == 0.75d;
                Debug.Assert(timePassed, "更新統計の集計", this);
                Check(timePassed, "更新統計の集計");

                agent.Pause();

                agent.Tick(1f);

                bool pausePassed =
                    agent.TickCount == 2 &&
                    agent.ElapsedTickTime == 0.75d;
                Debug.Assert(pausePassed, "一時停止中の更新抑止", this);
                Check(pausePassed, "一時停止中の更新抑止");

                agent.Resume();

                agent.Tick(0f);

                bool zeroPassed =
                    agent.TickCount == 2;
                Debug.Assert(zeroPassed, "経過時間0の更新省略", this);
                Check(zeroPassed, "経過時間0の更新省略");
            }
        }

        /// <summary>
        /// 状態変更イベントを検証する。
        /// </summary>
        private void TestEvents()
        {
            using (var parameters = CreateParameters())
            using (var agent = new TestAgent())
            {
                // 状態変更の通知件数。
                int eventCount = 0;

                // 最後に通知された変更前後の状態。
                AgentState previousState =
                    AgentState.Uninitialized;

                AgentState newState =
                    AgentState.Uninitialized;

                // 通知時に状態が確定済みかどうか。
                bool stateUpdated = false;

                Action<AgentState, AgentState> handler =
                    (previous, current) =>
                    {
                        eventCount++;

                        previousState = previous;

                        newState = current;

                        stateUpdated =
                            agent.State == current;
                    };

                agent.StateChanged += handler;

                try
                {
                    agent.Initialize(
                        CreateContext(parameters));

                    agent.Activate();

                    bool countPassed = eventCount == 2;
                    Debug.Assert(countPassed, "状態変更通知の件数", this);
                    Check(countPassed, "状態変更通知の件数");

                    bool statePassed =
                        previousState == AgentState.Inactive &&
                        newState == AgentState.Active &&
                        stateUpdated;
                    Debug.Assert(statePassed, "状態変更通知の引数", this);
                    Check(statePassed, "状態変更通知の引数");
                }
                finally
                {
                    agent.StateChanged -= handler;
                }

                agent.Pause();

                bool unsubscribePassed =
                    eventCount == 2;
                Debug.Assert(unsubscribePassed, "状態変更通知の購読解除", this);
                Check(unsubscribePassed, "状態変更通知の購読解除");
            }
        }

        /// <summary>
        /// 複数エージェントの独立性を検証する。
        /// </summary>
        private void TestIndependence()
        {
            using (var firstParameters = CreateParameters())
            using (var secondParameters = CreateParameters())
            using (var first = new TestAgent())
            using (var second = new TestAgent())
            {
                first.Initialize(
                    CreateContext(firstParameters));

                second.Initialize(
                    CreateContext(secondParameters));

                first.Activate();

                first.Tick(0.25f);

                bool individualPassed =
                    first.Id != second.Id &&
                    first.IsActive &&
                    !second.IsActive &&
                    first.TickCount == 1 &&
                    second.TickCount == 0;
                Debug.Assert(individualPassed, "個体識別と稼働状態の独立性", this);
                Check(individualPassed, "個体識別と稼働状態の独立性");

                firstParameters.SetBaseValue(
                    TestParameterId.Aggression,
                    0.9f);

                bool parameterPassed =
                    Mathf.Approximately(
                        first.Context.Parameters.GetValue(
                            TestParameterId.Aggression),
                        0.9f) &&
                    Mathf.Approximately(
                        second.Context.Parameters.GetValue(
                            TestParameterId.Aggression),
                        0.5f);
                Debug.Assert(parameterPassed, "個体別パラメーターの独立性", this);
                Check(parameterPassed, "個体別パラメーターの独立性");
            }
        }

        /// <summary>
        /// エージェントの破棄処理を検証する。
        /// </summary>
        private void TestDisposal()
        {
            using (var parameters = CreateParameters())
            using (var agent = new TestAgent())
            {
                agent.Initialize(CreateContext(parameters));

                agent.Activate();

                agent.Dispose();

                bool disposedPassed =
                    agent.IsDisposed &&
                    !agent.IsInitialized &&
                    !agent.IsTickEnabled &&
                    agent.Context == null;
                Debug.Assert(disposedPassed, "エージェントの破棄", this);
                Check(disposedPassed, "エージェントの破棄");

                agent.Dispose();

                agent.Tick(1f);

                bool duplicatePassed =
                    agent.DisposeCount == 1 &&
                    agent.TickCount == 0 &&
                    !agent.Activate() &&
                    !agent.Initialize(CreateContext(parameters));
                Debug.Assert(duplicatePassed, "破棄後の操作と重複破棄", this);
                Check(duplicatePassed, "破棄後の操作と重複破棄");

                bool ownershipPassed =
                    !parameters.IsDisposed &&
                    parameters.Count == 2;
                Debug.Assert(ownershipPassed, "外部パラメーター集合の所有権維持", this);
                Check(ownershipPassed, "外部パラメーター集合の所有権維持");
            }
        }

        /// <summary>
        /// 不正な引数と再入処理の拒否を検証する。
        /// </summary>
        private void TestInvalidInput()
        {
            using (var parameters = CreateParameters())
            using (var agent = new TestAgent())
            {
                bool namePassed =
                    Throws<ArgumentException>(() =>
                    {
                        new AgentContext<TestParameterId>(
                            "",
                            parameters);
                    });
                Debug.Assert(namePassed, "不正表示名の拒否", this);
                Check(namePassed, "不正表示名の拒否");

                bool nullPassed =
                    Throws<ArgumentNullException>(() =>
                    {
                        agent.Initialize(null);
                    });
                Debug.Assert(nullPassed, "null共有情報の拒否", this);
                Check(nullPassed, "null共有情報の拒否");

                agent.Initialize(CreateContext(parameters));

                agent.Activate();

                bool timePassed =
                    Throws<ArgumentOutOfRangeException>(() =>
                    {
                        agent.Tick(-1f);
                    });
                Debug.Assert(timePassed, "不正経過時間の拒否", this);
                Check(timePassed, "不正経過時間の拒否");

                // 更新処理の再入が拒否されるか確認する。
                bool reentryRejected = false;

                agent.TickAction = () =>
                {
                    reentryRejected =
                        Throws<InvalidOperationException>(() =>
                        {
                            agent.Tick(0.25f);
                        });
                };

                agent.Tick(0.25f);

                Debug.Assert(reentryRejected, "更新処理の再入防止", this);
                Check(reentryRejected, "更新処理の再入防止");

                // 状態変更通知中の再入が拒否されるか確認する。
                bool transitionRejected = false;

                Action<AgentState, AgentState> handler =
                    (previous, current) =>
                    {
                        transitionRejected =
                            Throws<InvalidOperationException>(() =>
                            {
                                agent.Resume();
                            });
                    };

                agent.StateChanged += handler;

                try
                {
                    agent.Pause();
                }
                finally
                {
                    agent.StateChanged -= handler;
                }

                Debug.Assert(transitionRejected, "状態遷移の再入防止", this);
                Check(transitionRejected, "状態遷移の再入防止");
            }
        }

        /// <summary>
        /// 指定された処理が期待する例外を発生させるか検証する。
        /// </summary>
        /// <typeparam name="TException">期待する例外型</typeparam>
        /// <param name="action">検証対象の処理</param>
        /// <returns>期待する例外が発生した場合はtrue</returns>
        private bool Throws<TException>(Action action)
            where TException : Exception
        {
            try
            {
                action();
            }
            catch (Exception exception)
            {
                if (exception.GetType() == typeof(TException))
                {
                    return true;
                }

                throw;
            }

            return false;
        }

        /// <summary>
        /// 個別のテスト結果を出力し、結果を集計する。
        /// </summary>
        /// <param name="passed">テストの成功判定</param>
        /// <param name="testName">テスト名</param>
        private void Check(bool passed, string testName)
        {
            if (passed)
            {
                passedCount++;

                Debug.Log(
                    $"<color=#00CC66>【成功】</color> {testName}",
                    this);
            }
            else
            {
                failedCount++;

                Debug.LogError(
                    $"【失敗】{testName}",
                    this);
            }
        }
    }
}
